EXACT_TARGET_CLEAT_SOURCE_X_CENTER = -107.725372
EXACT_TARGET_CLEAT_SOURCE_Y_CENTER = -5.0
EXACT_TARGET_CLEAT_SOURCE_BASE_Z = 3.0

DEFAULT_FRENCH_CLEAT_TEST_COUPON_WIDTH = 40.0
DEFAULT_FRENCH_CLEAT_TEST_COUPON_HEIGHT = 50.0
DEFAULT_FRENCH_CLEAT_TEST_COUPON_THICKNESS = 1.20
DEFAULT_FRENCH_CLEAT_TEST_SPACING = 60.0


def shape_from_brep_string(brep_data):
    shape = Part.Shape()
    shape.importBrepFromString(
        brep_data
    )
    return shape


def make_exact_pvc_french_cleat_hanger():
    """
    Return the PVC-side hanger exactly as modeled in cleat_example.step.

    This is not a reconstruction from dimensions. It is the literal
    OpenCASCADE BREP extracted from the reference STEP.
    """
    return shape_from_brep_string(
        EXACT_PVC_FRENCH_CLEAT_BREP
    )


def make_exact_target_french_cleat():
    """
    Return the exact target-side cleat from cleat_example.step,
    normalized so:

        X = 0 is the cleat center
        Y = 0 is the cleat bounding-box center
        Z = 0 is the target attachment plane

    The cleat dimensions are physical hardware dimensions and should
    never be scaled with the target.
    """
    cleat = shape_from_brep_string(
        EXACT_TARGET_FRENCH_CLEAT_BREP
    )

    cleat.translate(
        App.Vector(
            -EXACT_TARGET_CLEAT_SOURCE_X_CENTER,
            -EXACT_TARGET_CLEAT_SOURCE_Y_CENTER,
            -EXACT_TARGET_CLEAT_SOURCE_BASE_Z,
        )
    )

    return cleat


def make_exact_target_french_cleat_coupon(
    width=DEFAULT_FRENCH_CLEAT_TEST_COUPON_WIDTH,
    height=DEFAULT_FRENCH_CLEAT_TEST_COUPON_HEIGHT,
    thickness=DEFAULT_FRENCH_CLEAT_TEST_COUPON_THICKNESS,
):
    """
    Create a small flat coupon with the exact target-side cleat fused
    to its back for physical fit testing.
    """
    coupon = Part.makeBox(
        width,
        height,
        thickness,
        App.Vector(
            -width / 2,
            -height / 2,
            0,
        ),
    )

    cleat = make_exact_target_french_cleat()

    cleat.translate(
        App.Vector(
            0,
            0,
            thickness,
        )
    )

    return coupon.fuse(
        cleat
    ).removeSplitter()


def create_exact_target_french_cleat_coupon_test():
    """
    Create only the target-side coupon using the exact reference cleat.
    """
    document = App.newDocument(
        "Exact_Target_French_Cleat_Coupon"
    )

    coupon = document.addObject(
        "Part::Feature",
        "Exact_Target_French_Cleat_Coupon",
    )

    coupon.Label = (
        "Exact Target French Cleat Coupon"
    )

    coupon.Shape = (
        make_exact_target_french_cleat_coupon()
    )

    document.recompute()

    view = Gui.activeDocument().activeView()
    view.viewAxonometric()
    view.fitAll()

    return coupon


